def _normalize_repo_slug(remote_url: str) -> Optional[str]:
    if not remote_url:
        return None
    url = remote_url.strip()
    if url.startswith("git@") and ":" in url:
        url = url.split(":", 1)[1]
    elif "://" in url:
        url = url.split("://", 1)[1]
        if "/" in url:
            url = url.split("/", 1)[1]
    url = url.strip().rstrip("/")
    if url.endswith(".git"):
        url = url[:-4]
    return url or None


def _detect_repo_slug() -> Optional[str]:
    try:
        for name in ("origin", "upstream"):
            result = subprocess.run(
                ["git", "remote", "get-url", name],
                capture_output=True,
                text=True,
                check=False,
                timeout=3,
            )
            if result.returncode == 0:
                slug = _normalize_repo_slug(result.stdout.strip())
                if slug:
                    return slug
    except Exception:
        return None
    return None


