/**
 * GET /api/dx-metrics/productivity
 * Retrieves DX Core 4 productivity metrics for the current organization
 */
export async function GET(request: Request) {
  try {
    const { userId, getToken } = await auth();

    if (!userId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const rateLimit = await checkRateLimit(`dx-productivity:${userId}`, RateLimits.standard);
    if (!rateLimit.success) {
      return NextResponse.json(
        { error: "Rate limit exceeded" },
        { status: 429, headers: rateLimitHeaders(rateLimit) }
      );
    }

    const token = await getToken();
    if (!token) {
      return NextResponse.json({ error: "Authentication error" }, { status: 401 });
    }

    const { searchParams } = new URL(request.url);
    const rawDays = parseInt(searchParams.get("days") || "30", 10);
    const days = Math.max(7, Math.min(90, isNaN(rawDays) ? 30 : rawDays));

    const backendResponse = await fetch(
      `${BACKEND_URL}/v1/dx-metrics/productivity?days=${days}`,
      {
        method: "GET",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        next: { revalidate: 60 },
      }
    );

    if (!backendResponse.ok) {
      const errorText = await backendResponse.text();
      logger.error("Backend error fetching productivity metrics", {
        status: backendResponse.status,
        error: errorText,
      });
      return NextResponse.json(DEFAULT_PRODUCTIVITY_METRICS, {
        status: backendResponse.status,
      });
    }

    const data = await backendResponse.json();
    return NextResponse.json(data);
  } catch (error) {
    logger.error("Error fetching productivity metrics", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}
